import collections
import json
import os
import sys


def format_date(val):
    if val is None or val == "":
        return None
    val_str = str(val).strip()
    if len(val_str) >= 10 and val_str[4] == "-" and val_str[7] == "-":
        return val_str[:10]
    return val_str


def format_amount(val):
    if val is None or val == "":
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    return val_str


RULES = {
    "usa.period_3y": {
        "performance start": (
            "usaspending_awards",
            lambda r: format_date(
                (r.get("period_of_performance") or {}).get("start_date")
            ),
        ),
        "performance end": (
            "usaspending_awards",
            lambda r: format_date(
                (r.get("period_of_performance") or {}).get("end_date")
            ),
        ),
    },
    "usa.obligated_95": {
        "amount obligated": (
            "usaspending_awards",
            lambda r: format_amount(r.get("total_obligation")),
        ),
        "potential value": (
            "usaspending_awards",
            lambda r: format_amount(r.get("base_and_all_options")),
        ),
    },
}


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards_data = []
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=str, parse_int=str)

    entity_records = collections.defaultdict(list)
    if isinstance(awards_data, list):
        for item in awards_data:
            if not isinstance(item, dict):
                continue
            gid = item.get("generated_unique_award_id")
            if gid:
                entity_records[str(gid)].append(item)
            aid = item.get("id")
            if aid is not None and str(aid) != str(gid):
                entity_records[str(aid)].append(item)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        parts = pair.split("::", 1)
        if len(parts) != 2:
            continue
        rule_id, entity = parts

        fact_names = facts_by_rule.get(rule_id, [])
        rule_def = RULES.get(rule_id, {})

        pair_result = {}
        for fact_name in fact_names:
            if fact_name not in rule_def:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, extractor = rule_def[fact_name]
            records = entity_records.get(entity, [])

            extracted_values = []
            for r in records:
                val = extractor(r)
                if val is not None:
                    extracted_values.append(val)

            if not extracted_values:
                pair_result[fact_name] = "ABSENT"
            else:
                unique_values = list(dict.fromkeys(extracted_values))
                if len(unique_values) == 1:
                    pair_result[fact_name] = [unique_values[0], doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

