import sys
import os
import json
import collections
from decimal import Decimal

RULE_FACT_CONFIG = {
    "usa.period_3y": {
        "performance start": {
            "doc": "usaspending_awards",
            "path": ["period_of_performance", "start_date"],
            "type": "date"
        },
        "performance end": {
            "doc": "usaspending_awards",
            "path": ["period_of_performance", "end_date"],
            "type": "date"
        }
    },
    "usa.obligated_95": {
        "amount obligated": {
            "doc": "usaspending_awards",
            "path": ["total_obligation"],
            "type": "amount"
        },
        "potential value": {
            "doc": "usaspending_awards",
            "path": ["base_and_all_options"],
            "type": "amount"
        }
    }
}

def extract_path(obj, path):
    curr = obj
    for p in path:
        if isinstance(curr, dict):
            curr = curr.get(p)
        else:
            return None
    return curr

def format_date(val):
    if val is None:
        return None
    s = str(val).strip()
    if not s:
        return None
    if len(s) >= 10 and s[4] == '-' and s[7] == '-':
        return s[:10]
    return s

def format_amount(val):
    if val is None:
        return None
    s = str(val).strip()
    if not s:
        return None
    s = s.replace('$', '').replace(',', '')
    return s

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    awards_data = []
    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    if os.path.exists(awards_path):
        with open(awards_path, 'r', encoding='utf-8') as f:
            awards_data = json.load(f, parse_float=str, parse_int=str)

    awards_by_entity = collections.defaultdict(list)
    for award in awards_data:
        keys = set()
        gen_id = award.get("generated_unique_award_id")
        if gen_id:
            keys.add(gen_id)
        aid = award.get("id")
        if aid is not None:
            keys.add(str(aid))
        for k in keys:
            awards_by_entity[k].append(award)

    result = {}

    for pair in manifest.get("pairs", []):
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        fact_names = manifest.get("facts", {}).get(rule_id, [])
        matching_awards = awards_by_entity.get(entity, [])
        pair_result = {}

        for fact in fact_names:
            config = RULE_FACT_CONFIG.get(rule_id, {}).get(fact)
            if not config:
                pair_result[fact] = "ABSENT"
                continue

            doc_name = config["doc"]
            path = config["path"]
            val_type = config["type"]

            raw_vals = []
            for aw in matching_awards:
                v = extract_path(aw, path)
                if v is not None:
                    raw_vals.append(v)

            if not raw_vals:
                pair_result[fact] = "ABSENT"
                continue

            if val_type == "date":
                formatted_vals = []
                for rv in raw_vals:
                    fd = format_date(rv)
                    if fd is not None:
                        formatted_vals.append(fd)

                if not formatted_vals:
                    pair_result[fact] = "ABSENT"
                elif len(set(formatted_vals)) > 1:
                    pair_result[fact] = "CONFLICT"
                else:
                    pair_result[fact] = [formatted_vals[0], doc_name]

            elif val_type == "amount":
                parsed_vals = []
                for rv in raw_vals:
                    fa = format_amount(rv)
                    if fa is not None:
                        try:
                            d = Decimal(fa)
                            parsed_vals.append((d, fa))
                        except Exception:
                            parsed_vals.append((fa, fa))

                if not parsed_vals:
                    pair_result[fact] = "ABSENT"
                else:
                    first_val = parsed_vals[0][0]
                    has_conflict = any(pv[0] != first_val for pv in parsed_vals)
                    if has_conflict:
                        pair_result[fact] = "CONFLICT"
                    else:
                        pair_result[fact] = [parsed_vals[0][1], doc_name]
            else:
                pair_result[fact] = "ABSENT"

        result[pair] = pair_result

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

