import sys
import json
import os
import re
from collections import defaultdict

FACT_MAPPING = {
    "performance start": {
        "doc": "usaspending_awards",
        "path": ["period_of_performance", "start_date"],
        "type": "date"
    },
    "performance end": {
        "doc": "usaspending_awards",
        "path": ["period_of_performance", "end_date"],
        "type": "date"
    },
    "amount obligated": {
        "doc": "usaspending_awards",
        "path": ["total_obligation"],
        "type": "amount"
    },
    "potential value": {
        "doc": "usaspending_awards",
        "path": ["base_and_all_options"],
        "type": "amount"
    }
}


def get_nested(data, path):
    curr = data
    for key in path:
        if isinstance(curr, dict) and key in curr:
            curr = curr[key]
        else:
            return None
    return curr


def format_value(val, val_type):
    if val is None:
        return None
    if val_type == "date":
        s = str(val).strip()
        m = re.match(r"^(\d{4}-\d{2}-\d{2})", s)
        if m:
            return m.group(1)
        return s if s else None
    elif val_type == "amount":
        if isinstance(val, (int, float)):
            return str(val)
        s = str(val).strip()
        if not s:
            return None
        cleaned = re.sub(r"[^\d.-]", "", s)
        return cleaned if cleaned else s
    return str(val)


def values_conflict(val1, val2, val_type):
    if val_type == "amount":
        try:
            return float(val1) != float(val2)
        except (ValueError, TypeError):
            return val1 != val2
    return val1 != val2


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load usaspending_awards.json if present
    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    awards_by_id = defaultdict(list)

    if os.path.exists(awards_path):
        with open(awards_path, "r", encoding="utf-8") as f:
            try:
                awards_data = json.load(f)
                if isinstance(awards_data, list):
                    for item in awards_data:
                        if isinstance(item, dict):
                            award_id = item.get("generated_unique_award_id")
                            if award_id:
                                awards_by_id[award_id].append(item)
            except Exception:
                pass

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        rule_facts = facts_by_rule.get(rule_id, [])

        pair_result = {}
        for fact_name in rule_facts:
            fact_spec = FACT_MAPPING.get(fact_name)
            if not fact_spec:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name = fact_spec["doc"]
            field_path = fact_spec["path"]
            val_type = fact_spec["type"]

            records = awards_by_id.get(entity, [])
            if not records:
                pair_result[fact_name] = "ABSENT"
                continue

            found_values = []
            for rec in records:
                raw_val = get_nested(rec, field_path)
                formatted = format_value(raw_val, val_type)
                if formatted is not None:
                    found_values.append(formatted)

            if not found_values:
                pair_result[fact_name] = "ABSENT"
            else:
                has_conflict = False
                first_val = found_values[0]
                for v in found_values[1:]:
                    if values_conflict(first_val, v, val_type):
                        has_conflict = True
                        break

                if has_conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [first_val, doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

