import sys
import os
import json
from decimal import Decimal


def format_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    date_part = val_str.replace("T", " ").split()[0]
    return date_part


def get_performance_start(rec):
    pop = rec.get("period_of_performance")
    if isinstance(pop, dict):
        return pop.get("start_date")
    return None


def get_performance_end(rec):
    pop = rec.get("period_of_performance")
    if isinstance(pop, dict):
        return pop.get("end_date")
    return None


def get_amount_obligated(rec):
    return rec.get("total_obligation")


def get_potential_value(rec):
    return rec.get("base_and_all_options")


FACT_DEFINITIONS = {
    "performance start": ("usaspending_awards", "date", get_performance_start),
    "performance end": ("usaspending_awards", "date", get_performance_end),
    "amount obligated": ("usaspending_awards", "amount", get_amount_obligated),
    "potential value": ("usaspending_awards", "amount", get_potential_value),
}


def load_awards(packet_dir):
    awards_path = None
    for fname in os.listdir(packet_dir):
        if fname.lower() == "usaspending_awards.json":
            awards_path = os.path.join(packet_dir, fname)
            break

    if not awards_path or not os.path.isfile(awards_path):
        return {}

    with open(awards_path, "r", encoding="utf-8") as f:
        data = json.load(f, parse_float=Decimal, parse_int=Decimal)

    awards_by_id = {}
    if isinstance(data, list):
        for rec in data:
            if isinstance(rec, dict):
                award_id = rec.get("generated_unique_award_id")
                if award_id is not None:
                    awards_by_id.setdefault(str(award_id), []).append(rec)
    return awards_by_id


def evaluate_fact(matching_records, fact_name):
    if fact_name not in FACT_DEFINITIONS:
        return "ABSENT"

    doc_name, fact_type, extractor = FACT_DEFINITIONS[fact_name]

    if not matching_records:
        return "ABSENT"

    extracted_values = []
    for rec in matching_records:
        v = extractor(rec)
        if v is not None and v != "":
            extracted_values.append(v)

    if not extracted_values:
        return "ABSENT"

    if fact_type == "date":
        formatted_values = [format_date(v) for v in extracted_values]
        if any(d is None for d in formatted_values):
            return "ABSENT"
        if len(set(formatted_values)) > 1:
            return "CONFLICT"
        return [formatted_values[0], doc_name]

    elif fact_type == "amount":
        try:
            dec_values = [Decimal(str(v)) for v in extracted_values]
            if any(d != dec_values[0] for d in dec_values):
                return "CONFLICT"
            return [str(extracted_values[0]), doc_name]
        except Exception:
            str_values = [str(v) for v in extracted_values]
            if len(set(str_values)) > 1:
                return "CONFLICT"
            return [str_values[0], doc_name]

    else:
        str_values = [str(v) for v in extracted_values]
        if len(set(str_values)) > 1:
            return "CONFLICT"
        return [str_values[0], doc_name]


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_by_id = load_awards(packet_dir)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        rule_facts = facts_by_rule.get(rule_id, [])
        matching_records = awards_by_id.get(entity, [])

        pair_result = {}
        for fact_name in rule_facts:
            pair_result[fact_name] = evaluate_fact(matching_records, fact_name)

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

