import json
import os
import sys
from decimal import Decimal


def format_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    return val_str[:10]


def format_amount(val):
    if val is None:
        return None
    if isinstance(val, str):
        val = val.strip()
        if not val:
            return None
        return Decimal(val)
    if isinstance(val, (int, float, Decimal)):
        return Decimal(str(val))
    return None


FACT_EXTRACTORS = {
    ("usa.period_3y", "performance start"): (
        lambda rec: format_date(
            (rec.get("period_of_performance") or {}).get("start_date")
        ),
        "date",
    ),
    ("usa.period_3y", "performance end"): (
        lambda rec: format_date(
            (rec.get("period_of_performance") or {}).get("end_date")
        ),
        "date",
    ),
    ("usa.obligated_95", "amount obligated"): (
        lambda rec: format_amount(rec.get("total_obligation")),
        "amount",
    ),
    ("usa.obligated_95", "potential value"): (
        lambda rec: format_amount(rec.get("base_and_all_options")),
        "amount",
    ),
}

DEFAULT_FACTS = {
    "usa.period_3y": ["performance start", "performance end"],
    "usa.obligated_95": ["amount obligated", "potential value"],
}


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards = []
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards = json.load(f, parse_float=Decimal, parse_int=Decimal)

    records_by_entity = {}
    for award in awards:
        entity_id = award.get("generated_unique_award_id")
        if entity_id:
            records_by_entity.setdefault(entity_id, []).append(award)

    result = {}
    pairs = manifest.get("pairs", [])
    facts_map = manifest.get("facts", {})

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity_id = pair.split("::", 1)
        facts = facts_map.get(rule_id, DEFAULT_FACTS.get(rule_id, []))

        pair_result = {}
        entity_records = records_by_entity.get(entity_id, [])

        for fact in facts:
            extractor_info = FACT_EXTRACTORS.get((rule_id, fact))
            if not extractor_info:
                pair_result[fact] = "ABSENT"
                continue

            extractor, val_type = extractor_info
            values = []
            for rec in entity_records:
                extracted = extractor(rec)
                if extracted is not None:
                    values.append(extracted)

            if not values:
                pair_result[fact] = "ABSENT"
            else:
                first_val = values[0]
                if any(v != first_val for v in values):
                    pair_result[fact] = "CONFLICT"
                else:
                    pair_result[fact] = [str(first_val), "usaspending_awards"]

        result[pair] = pair_result

    print(json.dumps(result, indent=1))


if __name__ == "__main__":
    main()

